<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>@title — Umbraco.Bench</title>
    <link rel="stylesheet" href="~/dist/site.css" asp-append-version="true" />
    <style>
        .umb-block-grid {
            display: grid;
            grid-template-columns: repeat(var(--umb-block-grid--grid-columns, 12), minmax(0, 1fr));
        }
        .umb-block-grid__layout-item {
            grid-column: span var(--umb-block-grid--item-column-span, 12) / span var(--umb-block-grid--item-column-span, 12);
        }
    </style>
</head>
<body class="bg-slate-50 text-slate-800 min-h-screen flex flex-col">
    <header class="bg-slate-900 text-white">
        <nav class="mx-auto max-w-4xl px-6 py-4 flex items-center justify-between">
            <a href="/" class="text-lg font-semibold tracking-tight hover:text-amber-300">Umbraco.Bench</a>
            <a href="/" class="text-sm text-slate-300 hover:text-amber-300">Blog</a>
        </nav>
    </header>
    <main class="flex-1">
        @RenderBody()
    </main>
    <footer class="border-t border-slate-200 py-6 text-center text-sm text-slate-500">
        Built with Umbraco blocks over the Model Context Protocol.
    </footer>
</body>
</html>
