@using Umbraco.Bench.Umbraco.Models
@using Umbraco.Extensions
@inherits UmbracoViewPage<BlogFrontPage>
@{
    Layout = "_Layout.cshtml";
    var posts = Model.Children<BlogPostPage>().OrderByDescending(p => p.PostDate).ToList();
}
@await Html.GetBlockGridHtmlAsync(Model, "blocks")
<section class="mx-auto max-w-4xl px-6 py-12">
    <h2 class="text-xl font-bold text-slate-900 border-b border-slate-200 pb-2">Latest posts</h2>
    @if (!posts.Any())
    {
        <p class="mt-4 text-slate-500">No posts yet.</p>
    }
    <div class="mt-6 grid gap-6 sm:grid-cols-2">
        @foreach (var post in posts)
        {
            <a href="@post.Url()" class="group flex flex-col overflow-hidden rounded-lg border border-slate-200 bg-white shadow-sm transition hover:shadow-md">
                @if (post.HeroImage is not null)
                {
                    <img src="@post.HeroImage.GetCropUrl(width: 800, height: 450)" class="h-48 w-full object-cover" alt="" />
                }
                <div class="flex flex-col gap-2 p-5">
                    <span class="text-xs uppercase tracking-wide text-slate-500">@post.PostDate.ToString("MMMM d, yyyy")</span>
                    <h3 class="text-lg font-semibold text-slate-900 group-hover:text-amber-600">@post.Name</h3>
                    <p class="text-sm text-slate-600">@post.Excerpt</p>
                    <span class="mt-auto pt-3 text-sm font-medium text-amber-600">Read more →</span>
                </div>
            </a>
        }
    </div>
</section>
